/**
 *  `credential://request` 事件负载：前端据此渲染三动作对话框
 *  （Submit / Cancel / Remember）。
 */
export type CredentialPrompt = 
/**  HTTPS 凭据请求（credential helper get 未命中）。 */
{ kind: "https"; request_id: string; protocol: string; host: string; path: string | null; username: string | null } | 
/**  askpass 提示（口令短语 / 用户名 / 密码兜底）。 */
{ kind: "askpass"; request_id: string; prompt: string; 
/**  提示是索取用户名（普通输入框）还是机密（密码框）。 */
is_secret: boolean } | 
/**  SSH host key 首次确认（指纹展示 + 信任记忆）。 */
{ kind: "host_key"; request_id: string; prompt: string; fingerprint: string | null; host: string | null };

/**  前端 `credential_respond` 的应答（PLAN P7 三动作）。 */
export type CredentialReply = 
/**  HTTPS/askpass 提交；`remember` = 写入 keychain（批准后生效，见 §6）。 */
{ action: "submit"; username: string | null; secret: string | null; remember: boolean } | 
/**  host key：信任（应答 yes；remember = 存入信任库）。 */
{ action: "trust_host_key"; remember: boolean } | 
/**  用户取消 → CredentialCancelled。 */
{ action: "cancel" };

export type DiffFile = {
	old_path: string | null,
	new_path: string | null,
	similarity: number | null,
	binary: boolean,
	hunks: DiffHunk[],
};

export type DiffHunk = {
	old_start: number,
	old_count: number,
	new_start: number,
	new_count: number,
	header: string,
	lines: DiffLine[],
};

export type DiffLine = {
	content: string,
	left_no: number | null,
	right_no: number | null,
	kind: DiffLineKind,
	/**
	 *  The line is followed by `\\ No newline at end of file`: the file on
	 *  this line's side ends without a trailing newline. Only the genuine
	 *  last line of a side can carry this; the patch builder uses it to
	 *  reproduce correct `\\ No newline` markers (P4 行级暂存边界用例).
	 */
	no_eol?: boolean,
};

export type DiffLineKind = "context" | "add" | "remove" | "header";

export type DiffModel = {
	/**
	 *  Identity of the cached model on the Rust side (PLAN P4: 行级操作由前端
	 *  上报 model id + 行号，Rust 从同一模型构造 patch，杜绝双端解析漂移).
	 *  0 = not cached (parse-time default).
	 */
	id?: number,
	source: DiffSource,
	old_revision: string | null,
	new_revision: string | null,
	files: DiffFile[],
};

export type DiffSource = "worktree" | "staged" | "commit" | "stash";

/**
 *  One commit of a single file's history (`git log --follow`, P9 文件追溯).
 *  Entries are newest first; the path fields track the file across renames.
 */
export type FileCommit = {
	hash: string,
	short_hash: string,
	author: string,
	email: string,
	date: string,
	message: string,
	parents: string[],
	/**  The path this file had **at this commit** (for renames: the new path). */
	path: string,
	/**  Old path when this commit renamed/copied the file (`R`/`C` entry). */
	orig_path: string | null,
	/**  name-status letter of this file in the commit: A/M/D/T/R/C. */
	status: string,
	/**  Rename/copy similarity score (e.g. `93` for `R93`). */
	score: number | null,
};

/**
 *  Content of one file revision (worktree or a git object), base64-encoded
 *  for the wire; `data` is `None` when the file exceeds the transfer cap.
 */
export type FileContent = {
	/**
	 *  Saturates at `u32::MAX` for absurd sizes (the UI only needs a
	 *  "too large" signal past the transfer cap).
	 */
	size: number,
	data: string | null,
};

export type FileStatus = FileStatus_Serialize | FileStatus_Deserialize;

export type FileStatus_Deserialize = {
	path: string,
	status: string,
	orig_path: string | null,
	submodule: boolean,
	/**  Submodule with modified content (porcelain v2 `sub = S`). */
	submodule_dirty: boolean,
	/**  Submodule whose checked-in commit differs from the index (`sub = M`). */
	submodule_commit_changed: boolean,
	/**
	 *  The worktree change consists only of line-ending differences
	 *  (CRLF/LF); detected via the `--ignore-cr-at-eol` numstat diff.
	 */
	eol_only: boolean,
	staged: boolean,
	unstaged: boolean,
	untracked: boolean,
	/**  skip-worktree (porcelain v2 XY contains `S`). */
	skipped: boolean,
	conflict: boolean,
};

export type FileStatus_Serialize = {
	path: string,
	status: string,
	orig_path?: string | null,
	submodule: boolean,
	/**  Submodule with modified content (porcelain v2 `sub = S`). */
	submodule_dirty: boolean,
	/**  Submodule whose checked-in commit differs from the index (`sub = M`). */
	submodule_commit_changed: boolean,
	/**
	 *  The worktree change consists only of line-ending differences
	 *  (CRLF/LF); detected via the `--ignore-cr-at-eol` numstat diff.
	 */
	eol_only: boolean,
	staged: boolean,
	unstaged: boolean,
	untracked: boolean,
	/**  skip-worktree (porcelain v2 XY contains `S`). */
	skipped: boolean,
	conflict: boolean,
};

/**
 *  The global gitignore file (`core.excludesFile` or the platform default
 *  `~/.config/git/ignore`), read for the read-only viewer.
 */
export type GitignoreFile = {
	/**  Resolved absolute path (display purpose). */
	path: string,
	/**  Raw file content (lossy UTF-8). */
	content: string,
};

/**  One edge segment drawn within a single commit row. */
export type GraphEdge = {
	/**  Lane (column) where the edge starts on this row. */
	from: number,
	/**  Lane (column) where the edge ends on this row. */
	to: number,
	/**  The edge starts at this row's node (mid-height, lower half). */
	from_node: boolean,
	/**  The edge ends at this row's node (mid-height, upper half). */
	to_node: boolean,
};

/**  Search/filter for the history graph query (PLAN P5 搜索/筛选). */
export type GraphFilter = {
	/**
	 *  Message search (`--grep -i`). A pure-hex prefix of ≥ 4 chars is
	 *  treated as a hash jump instead: it resolves via `rev-parse` and the
	 *  graph starts at that commit.
	 */
	text: string | null,
	/**  Author substring (`--author -i`). */
	author: string | null,
	/**  `--since` (git date, e.g. `2026-01-01`). */
	since: string | null,
	/**  `--until`. */
	until: string | null,
	/**  History touching any of these paths. */
	paths: string[],
};

/**
 *  One page of the commit graph served by the GraphCache (P5). `start` is
 *  the row index of `rows[0]` within the full graph: `0` means the cache
 *  was rebuilt and the frontend must replace its list, otherwise the rows
 *  append after the previously loaded ones.
 */
export type GraphPage = {
	rows: GraphRow[],
	start: number,
	/**  `git log` exhausted — no further pages. */
	complete: boolean,
	/**  Lanes used so far (SVG column count). */
	width: number,
};

/**
 *  One rendered row of the commit graph: the commit plus its lane and the
 *  edge segments crossing the row.
 */
export type GraphRow = {
	commit: CommitInfo,
	/**  Column of this commit's node. */
	lane: number,
	edges: GraphEdge[],
};

/**
 *  `workspaces/groups.json` — the long-lived organizational layer over the
 *  repo collection. Unlike `recents.json` (bounded recently-opened list),
 *  group membership and stars must survive recents truncation, hence a
 *  separate file (PLAN P3.5).
 */
export type GroupsFile = GroupsFile_Serialize | GroupsFile_Deserialize;

/**
 *  `workspaces/groups.json` — the long-lived organizational layer over the
 *  repo collection. Unlike `recents.json` (bounded recently-opened list),
 *  group membership and stars must survive recents truncation, hence a
 *  separate file (PLAN P3.5).
 */
export type GroupsFile_Deserialize = {
	version?: number,
	groups?: RepoGroup[],
	/**
	 *  Resolved repo path → metadata. Keys use the resolved worktree root
	 *  (same normalization as `RepoId`) to avoid Windows case ambiguity.
	 */
	repos?: { [key in string]: RepoMeta_Deserialize },
};

/**
 *  `workspaces/groups.json` — the long-lived organizational layer over the
 *  repo collection. Unlike `recents.json` (bounded recently-opened list),
 *  group membership and stars must survive recents truncation, hence a
 *  separate file (PLAN P3.5).
 */
export type GroupsFile_Serialize = {
	version: number,
	groups: RepoGroup[],
	/**
	 *  Resolved repo path → metadata. Keys use the resolved worktree root
	 *  (same normalization as `RepoId`) to avoid Windows case ambiguity.
	 */
	repos: { [key in string]: RepoMeta_Serialize },
};

/**  已信任的 SSH host key 条目。 */
export type KnownHost = {
	host: string,
	fingerprint: string,
};

/**
 *  One selected diff line for line-level operations (P4 行级暂存): indices
 *  into the cached [`DiffModel`] the frontend is displaying.
 */
export type LineSelection = {
	/**  Index into `DiffFile.hunks`. */
	hunk: number,
	/**  Index into `DiffHunk.lines`. */
	line: number,
};

export type MergeResult = {
	success: boolean,
	message: string,
};

/**  前端下发的网络配置（settings.json 持久化在前端 store）。 */
export type NetConfig = {
	/**  `inherit` | `none` | `custom` */
	proxy_mode: string,
	proxy_url: string | null,
	ssh_key_path: string | null,
};

/**  In-progress repository operation (P8 仓库状态头: merge/rebase/…). */
export type OperationKind = "merge" | "rebase" | "cherry_pick" | "revert" | 
/**  `git am` residue (rebase-apply without rebase files). */
"apply" | "bisect";

/**  What the frontend needs for the operation guidance banner. */
export type OperationState = {
	kind: OperationKind,
	/**  Head being merged/rebased onto (full sha; frontend truncates). */
	onto: string | null,
	/**  1-based step within the sequence (rebase/cherry-pick sequences). */
	step: number | null,
	total: number | null,
	/**  `MERGE_MSG` (merge/cherry-pick/revert) for the commit prefill. */
	message: string | null,
};

/**
 *  Provider 类型矩阵（ADR-013 决策 4）：一个 OpenAI 兼容客户端覆盖
 *  OpenAI / Ollama / DeepSeek / Qwen / Moonshot / vLLM / LM Studio；
 *  Anthropic Messages API；自定义 HTTP（OpenAI 兼容 wire format + 完整 URL）。
 */
export type ProviderKind = 
/**  本地离线选项（设置页置顶，隐私红线：数据不出本机）。 */
"ollama" | 
/**  OpenAI 及一切兼容端点。 */
"open_ai_compatible" | 
/**  Anthropic Messages API。 */
"anthropic" | 
/**  自定义 HTTP：`base_url` 填**完整**端点 URL，请求体为 OpenAI 兼容格式。 */
"custom";

export type PullResult = {
	success: boolean,
	message: string,
	fast_forward: boolean,
};

export type RebaseState = {
	state: string,
	current_step: number,
	total_steps: number,
	current_commit: string | null,
};

export type RecentRepo = {
	path: string,
	name: string,
	/**  Unix timestamp (seconds) of the last open. f64 for JS-safe export. */
	last_opened: number | null,
};

/**
 *  Frontend-facing summary of one snapshot (specta type).
 *  Timestamps/counts use f64 on the wire: u64 is JS-precision-unsafe and
 *  specta forbids it; all values stay below 2^53.
 */
export type RecoveryEntry = {
	id: string,
	created_at_ms: number | null,
	kind: string,
	scope: string,
	file_count: number,
	size_bytes: number | null,
	warnings: string[],
};

export type ReflogEntry = {
	hash: string,
	short_hash: string,
	ref_name: string,
	message: string,
	date: string,
	author: string,
};

export type RemoteInfo = {
	name: string,
	url: string,
	fetch_url: string,
	push_url: string,
};

/**
 *  Typed event delivered to the frontend after an invalidation cycle
 *  completed and caches were re-read (tauri-specta generated bindings).
 */
export type RepoChanged = RepoChanged_Serialize | RepoChanged_Deserialize;

/**
 *  Typed event delivered to the frontend after an invalidation cycle
 *  completed and caches were re-read (tauri-specta generated bindings).
 */
export type RepoChanged_Deserialize = {
	repoId: RepoId_Deserialize,
	kinds: string[],
	generation: number,
};

/**
 *  Typed event delivered to the frontend after an invalidation cycle
 *  completed and caches were re-read (tauri-specta generated bindings).
 */
export type RepoChanged_Serialize = {
	repoId: RepoId_Serialize,
	kinds: string[],
	generation: number,
};

/**
 *  One common config key resolved for a repository (P10 仓库设置): the
 *  repo-local value (`.git/config`) and the effective value git would use
 *  (merged system + global + local). `local == None` 意味着继承上层作用域。
 */
export type RepoConfigValue = {
	key: string,
	/**  Value written in the repo-local config; `None` = no local override. */
	local: string | null,
	/**  Effective value after merging all scopes; `None` = not set anywhere. */
	effective: string | null,
};

/**  A named repository group (flat, v1 — no nesting; PLAN P3.5). */
export type RepoGroup = {
	/**  Stable id (generated at creation, survives renames). */
	id: string,
	name: string,
	/**  Display order (creation order); the UI sorts groups by this. */
	order: number,
};

/**
 *  RepoId: FNV-1a hash of the worktree path. Serialized as a string on the
 *  wire — u64 exceeds JS `Number.MAX_SAFE_INTEGER` and would truncate.
 */
export type RepoId = RepoId_Serialize | RepoId_Deserialize;

/**
 *  RepoId: FNV-1a hash of the worktree path. Serialized as a string on the
 *  wire — u64 exceeds JS `Number.MAX_SAFE_INTEGER` and would truncate.
 */
export type RepoId_Deserialize = string;

/**
 *  RepoId: FNV-1a hash of the worktree path. Serialized as a string on the
 *  wire — u64 exceeds JS `Number.MAX_SAFE_INTEGER` and would truncate.
 */
export type RepoId_Serialize = string;

/**
 *  Per-repo organizational metadata (PLAN P3.5). Entries exist only while
 *  meaningful: [`update_repo`] drops an entry when it becomes the default.
 */
export type RepoMeta = RepoMeta_Serialize | RepoMeta_Deserialize;

/**
 *  Per-repo organizational metadata (PLAN P3.5). Entries exist only while
 *  meaningful: [`update_repo`] drops an entry when it becomes the default.
 */
export type RepoMeta_Deserialize = {
	/**  Group the repo belongs to (`None` = ungrouped). */
	group_id?: string | null,
	/**
	 *  Colorful bookmark (palette id, e.g. `red`/`blue`); `None` = unmarked.
	 *  The palette itself is a frontend display concern.
	 */
	bookmark?: string | null,
};

/**
 *  Per-repo organizational metadata (PLAN P3.5). Entries exist only while
 *  meaningful: [`update_repo`] drops an entry when it becomes the default.
 */
export type RepoMeta_Serialize = {
	/**  Group the repo belongs to (`None` = ungrouped). */
	group_id?: string | null,
	/**
	 *  Colorful bookmark (palette id, e.g. `red`/`blue`); `None` = unmarked.
	 *  The palette itself is a frontend display concern.
	 */
	bookmark?: string | null,
};

/**
 *  Per-repo UI state (PLAN §4.4). The frontend owns the contents; this is a
 *  typed contract so the wire format stays stable. Extend with new
 *  `#[serde(default)]` fields only — never remove/rename existing ones.
 */
export type RepoUiState = RepoUiState_Serialize | RepoUiState_Deserialize;

/**
 *  Per-repo UI state (PLAN §4.4). The frontend owns the contents; this is a
 *  typed contract so the wire format stays stable. Extend with new
 *  `#[serde(default)]` fields only — never remove/rename existing ones.
 */
export type RepoUiState_Deserialize = {
	view?: string | null,
	filter?: string,
	sidebar_collapsed?: string[],
	selected_file?: SelectedFile | null,
	/**  Workspace list mode: `list` (flat sections) or `tree` (path tree). */
	view_mode?: string | null,
	/**  Collapsed directory ids in tree mode. */
	tree_collapsed?: string[],
};

/**
 *  Per-repo UI state (PLAN §4.4). The frontend owns the contents; this is a
 *  typed contract so the wire format stays stable. Extend with new
 *  `#[serde(default)]` fields only — never remove/rename existing ones.
 */
export type RepoUiState_Serialize = {
	view?: string | null,
	filter?: string,
	sidebar_collapsed?: string[],
	selected_file?: SelectedFile | null,
	/**  Workspace list mode: `list` (flat sections) or `tree` (path tree). */
	view_mode?: string | null,
	/**  Collapsed directory ids in tree mode. */
	tree_collapsed?: string[],
};

/**  What the frontend needs to undo one reset (PLAN P6: 一键撤销). */
export type ResetUndo = {
	/**  Backup ref created at the pre-reset HEAD (track B). */
	backup_ref: string,
	/**  Track-A snapshot id (hard resets only; restores index + worktree). */
	snapshot_id: string | null,
};

/**  Selected diff target in the workspace view (frontend-owned UI state). */
export type SelectedFile = {
	path: string,
	/**  `worktree` or `staged` — which diff to show for the file. */
	source: string,
};

/**  生成算法（specta：`{ kind: "ed25519" } | { kind: "rsa"; bits: number }`）。 */
export type SshKeyAlgorithm = { kind: "ed25519" } | { kind: "rsa"; bits: number };

/**  生成参数。 */
export type SshKeyGenerateRequest = {
	algorithm: SshKeyAlgorithm,
	/**  公钥注释（追加在 `.pub` 行尾；空 = 不写注释）。 */
	comment: string | null,
	/**  私钥口令；空 / None = 不加密。 */
	passphrase: string | null,
	/**  文件名（相对 `~/.ssh`）；None / 空 = 按算法自动命名，占用则追加序号。 */
	file_name: string | null,
};

/**  密钥条目（列表页）。 */
export type SshKeyInfo = {
	/**  `.pub` 路径。 */
	public_path: string,
	/**  私钥路径；None = 目录里只有公钥（不能设为活动密钥）。 */
	private_path: string | null,
	algorithm: string,
	bits: number,
	/**  `SHA256:<base64>`。 */
	fingerprint: string,
	comment: string,
	/**  私钥是否用口令加密。 */
	encrypted: boolean,
	/**  单行 openssh 公钥文本（复制给 Git 托管平台用）。 */
	public_key: string,
};

export type StashEntry = {
	/**  Position in the stash stack (`stash@{N}`); u32 on the wire. */
	index: number,
	message: string,
	branch: string | null,
	date: string,
};

export type TagInfo = {
	name: string,
	full_name: string,
	target: string,
	tagger: string | null,
	date: string | null,
	message: string | null,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

